"""Contact sheet rows for substitute teachers."""

from typing import List, Sequence, Tuple

from rosterkit.errors import ProjectError
from rosterkit.models import Student


def _checked(students: Sequence[Student]) -> List[Student]:
    """Students sorted by name, refusing empty input or a missing email."""
    if not students:
        raise ProjectError("cannot build a contact sheet from an empty list")
    for stud in students:
        if not (stud.email or "").strip():
            raise ProjectError(f"no email for student {stud.display_name}")
    return sorted(students, key=lambda stud: stud.display_name.lower())


def _join(entry: Tuple[str, ...], widths: List[int]) -> str:
    return "  ".join(text.ljust(wide) for text, wide in zip(entry, widths)).rstrip()

# ---
def contact_rows(students: Sequence[Student]) -> List[str]:
    """Text rows of name, section and email in columns, sorted by name."""
    ordered = _checked(students)
    cells = [(stud.display_name, stud.section, stud.email.strip()) for stud in ordered]
    widths = [max(len(text) for text in column) for column in zip(*cells)]
    return [_join(entry, widths) for entry in cells]

