# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.errors import ProjectError
from rosterkit.models import Student

def make_student(last, first, section="A", email="x@example.org"):
    return Student(f"{last}{first}", last, first, section, email)

class ContactRowsTests(unittest.TestCase):
    def test_rows_are_sorted_by_name(self):
        rows = contact_rows([make_student("Zed", "Amy"), make_student("Abe", "Bob")])
        self.assertTrue(rows[0].startswith("Abe, Bob"))
        self.assertTrue(rows[1].startswith("Zed, Amy"))

    def test_columns_line_up(self):
        rows = contact_rows([
            make_student("Li", "Al", "A", "al@example.org"),
            make_student("Longname", "Beth", "B12", "beth@example.org")
        ])
        self.assertEqual(rows[0].index("A "), rows[1].index("B12"))
        self.assertEqual(rows[0].index("al@"), rows[1].index("beth@"))

    def test_row_holds_name_section_and_email(self):
        rows = contact_rows([make_student("Li", "Al", "C", "al@example.org")])
        self.assertEqual(rows, ["Li, Al  C  al@example.org"])

    def test_missing_email_names_the_student(self):
        with self.assertRaises(ProjectError) as caught:
            contact_rows([make_student("Li", "Al"), make_student("Roe", "Jo", email=None)])
        self.assertIn("Roe, Jo", str(caught.exception))

    def test_blank_email_is_missing(self):
        with self.assertRaises(ProjectError):
            contact_rows([make_student("Roe", "Jo", email="  ")])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])

if __name__ == "__main__":
    unittest.main()
